<?php
namespace ZinCelestial\Platform\Rewards;
final class RewardsHooks{private static $i;public static function instance(){if(!self::$i)self::$i=new self();return self::$i;}public function register(){if(!function_exists('buddypress'))return;add_action('bp_directory_members_item',array($this,'directory'),30);add_action('bp_before_member_header_meta',array($this,'profile'),30);add_action('bp_activity_entry_content',array($this,'activity'),30);}public function directory(){if(function_exists('bp_get_member_user_id'))RewardsView::render('user',absint(bp_get_member_user_id()),'directory');}public function profile(){if(function_exists('bp_displayed_user_id'))RewardsView::render('user',absint(bp_displayed_user_id()),'profile');}public function activity(){if(function_exists('bp_get_activity_user_id'))RewardsView::render('user',absint(bp_get_activity_user_id()),'activity');}}
